// Normalización y validación estricta de la solicitud entrante
let body = $json.body !== undefined ? $json.body : $json;
if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch (e) {}
}

if (!body || typeof body !== 'object') {
  return [{
    json: {
      isValid: false,
      errorCode: 'INVALID_BODY',
      errorMessage: 'El cuerpo de la solicitud debe ser un objeto JSON válido.',
      action: 'unknown'
    }
  }];
}

const action = body.action;

if (action === 'clasificar_gasto') {
  if (!body.descripcion || typeof body.descripcion !== 'string' || body.descripcion.trim().length === 0) {
    return [{
      json: {
        isValid: false,
        errorCode: 'MISSING_DESCRIPTION',
        errorMessage: 'El campo "descripcion" es obligatorio para clasificar el gasto.',
        action
      }
    }];
  }

  const promptText = `Acción solicitada: clasificar_gasto\nDescripción del gasto: "${body.descripcion.trim()}"\n\nInstrucción: Clasifica este gasto exactamente en una de las siguientes categorías permitidas: Vivienda, Alimentación, Transporte, Servicios, Entretenimiento, Salud, Educación, Viajes, Compras, Otros.\n\nDevuelve obligatoriamente un JSON con esta estructura exacta:\n{\n  "ok": true,\n  "data": {\n    "categoria": "<CategoriaSeleccionada>",\n    "confianza": 0.95,\n    "justificacion": "<Breve explicacion de por que corresponde a esta categoria>"\n  },\n  "error": null\n}`;

  return [{
    json: {
      isValid: true,
      action,
      prompt: promptText,
      rawInput: body
    }
  }];
}

if (action === 'resumen_mensual') {
  const grupoId = body.grupo_id;
  const mes = body.mes || 'Mes actual';
  const gastos = Array.isArray(body.gastos) ? body.gastos : [];
  const balances = Array.isArray(body.balances) ? body.balances : [];

  const promptText = `Acción solicitada: resumen_mensual\nGrupo ID: ${grupoId}\nMes evaluado: ${mes}\nCantidad de gastos en el mes: ${gastos.length}\nListado de gastos: ${JSON.stringify(gastos)}\nBalances actuales de los integrantes: ${JSON.stringify(balances)}\n\nInstrucción: Analiza los gastos y balances proporcionados. No inventes montos ni agregues información inexistente. Calcula la categoría en la que más se gastó y genera recomendaciones prudentes para liquidar deudas o moderar consumos.\n\nDevuelve obligatoriamente un JSON con esta estructura exacta:\n{\n  "ok": true,\n  "data": {\n    "grupo_id": ${grupoId},\n    "mes": "${mes}",\n    "total_gastado": "<TotalSumadoFormatoDecimal>",\n    "categoria_principal": "<CategoriaMasGastada>",\n    "resumen": "<Parrafo en lenguaje natural analizando el comportamiento de los gastos>",\n    "recomendaciones": [\n      "<Recomendacion 1>",\n      "<Recomendacion 2>"\n    ]\n  },\n  "error": null\n}`;

  return [{
    json: {
      isValid: true,
      action,
      prompt: promptText,
      rawInput: body
    }
  }];
}

return [{
  json: {
    isValid: false,
    errorCode: 'ACTION_UNKNOWN',
    errorMessage: `Acción desconocida "${action}". Acciones permitidas: clasificar_gasto, resumen_mensual.`,
    action
  }
}];

