// Herramienta de cálculo para el agente
try {
  const input = typeof query === 'string' ? JSON.parse(query) : query;
  if (Array.isArray(input)) {
    const sum = input.reduce((acc, curr) => acc + (Number(curr) || 0), 0);
    return JSON.stringify({ suma: sum.toFixed(2) });
  }
  return JSON.stringify({ resultado: input });
} catch (e) {
  return JSON.stringify({ error: e.message });
}

// Extracción y validación segura de la respuesta generada por el AI Agent
const rawOutput = $json.output || $json.text || JSON.stringify($json);

let cleaned = String(rawOutput).trim();
// Eliminar posibles bloques de markdown si el LLM los generó
cleaned = cleaned.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();

try {
  const parsed = JSON.parse(cleaned);
  if (parsed && typeof parsed === 'object' && typeof parsed.ok === 'boolean') {
    return [{
      json: parsed
    }];
  }
  if (parsed && typeof parsed === 'object') {
    return [{
      json: {
        ok: true,
        data: parsed,
        error: null
      }
    }];
  }
} catch (err) {
  // Intento de extracción mediante regex si hay texto adicional
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      const extracted = JSON.parse(match[0]);
      return [{
        json: {
          ok: true,
          data: extracted.data || extracted,
          error: null
        }
      }];
    } catch (e) {}
  }
}

// Error controlado si el modelo no devolvió JSON interpretable
return [{
  json: {
    ok: false,
    data: null,
    error: {
      code: 'INVALID_AI_RESPONSE',
      message: 'El agente de IA no devolvió una respuesta JSON conforme al contrato establecido.'
    }
  }
}];

// Respuesta de error para entradas inválidas (acción desconocida o campos faltantes)
return [{
  json: {
    ok: false,
    data: null,
    error: {
      code: $json.errorCode || 'BAD_REQUEST',
      message: $json.errorMessage || 'Parámetros de solicitud inválidos para el agente de IA.'
    }
  }
}];
